package com.landportal.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="documents") public class Document { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(optional=false) AcquisitionCase acquisitionCase; String documentType,filename,storagePath; LocalDateTime uploadedAt; @ManyToOne(optional=false) User uploadedBy; public Long getId(){return id;} public AcquisitionCase getAcquisitionCase(){return acquisitionCase;} public void setAcquisitionCase(AcquisitionCase v){acquisitionCase=v;} public String getDocumentType(){return documentType;} public void setDocumentType(String v){documentType=v;} public String getFilename(){return filename;} public void setFilename(String v){filename=v;} public String getStoragePath(){return storagePath;} public void setStoragePath(String v){storagePath=v;} public LocalDateTime getUploadedAt(){return uploadedAt;} public void setUploadedAt(LocalDateTime v){uploadedAt=v;} public User getUploadedBy(){return uploadedBy;} public void setUploadedBy(User v){uploadedBy=v;} @PrePersist void init(){uploadedAt=LocalDateTime.now();} }
